  SELECT LAST_INSERT_ID()

insert into think_data_detail (think_data_id, data_type, org_id, 
  org_name, state, dep_acc_mony, 
  lefan_in_mony, lefan_out_mony, lefan_tax_mony
  )
values (#{thinkDataId,jdbcType=BIGINT}, #{dataType,jdbcType=INTEGER}, #{orgId,jdbcType=BIGINT}, 
  #{orgName,jdbcType=VARCHAR}, #{state,jdbcType=INTEGER}, #{depAccMony,jdbcType=DOUBLE}, 
  #{lefanInMony,jdbcType=DOUBLE}, #{lefanOutMony,jdbcType=DOUBLE}, #{lefanTaxMony,jdbcType=DOUBLE}
  )

mapper.select:
select
d.*
from think_data_detail d
left join staff_organ o on d.org_id = o.id
where 1 = 1

  and d.think_data_id = #{thinkDataId,jdbcType=BIGINT}


  and d.org_id = #{orgId,jdbcType=BIGINT}


  and d.data_type = #{dataType,jdbcType=BIGINT}



  and (
    1 = 2

        or o.organ_manager_user_id = #{curUserId,jdbcType=BIGINT}


        or o.superior_manager_user_id = #{curUserId,jdbcType=BIGINT}


        or data_type = 4


        or 1 = 1

    )
